function DemoTag({ children, tone = "neutral" }: { children: string; tone?: "good" | "warn" | "bad" | "neutral" }) {
  return <span className={`status-pill ${tone}`}><i />{children}</span>;
}

function DemoBanner({ label, title, description, children }: { label: string; title: string; description: string; children?: React.ReactNode }) {
  return <section className="demo-section-banner"><div><span>{label}</span><h2>{title}</h2><p>{description}</p></div>{children}</section>;
}

function EmptyState({ title, detail, action, onAction }: { title: string; detail: string; action?: string; onAction?: () => void }) {
  return <div className="operational-empty"><span>◇</span><strong>{title}</strong><p>{detail}</p>{action && <button className="primary-button" onClick={onAction}>{action}</button>}</div>;
}

