type RecordingManifestItem = { file: string; durationSeconds: number; generation?: string };
type RecordingManifest = { recordingBaseline: string; recordings: RecordingManifestItem[] };
const formatRecordingDuration = (seconds: number) => {
  const rounded = Math.round(seconds);
  return `${String(Math.floor(rounded / 60)).padStart(2, "0")}:${String(rounded % 60).padStart(2, "0")}`;
};
